class Solution {
public:
    int countHousePlacements(int n) {
        long long MOD = 1e9 + 7;
        long long a = 1, b = 2;
        for (int i = 0; i < n; ++i) {
            long long next_b = (a + b) % MOD;
            a = b;
            b = next_b;
        }
        return (a * a) % MOD;
    }
};

class Solution {
    public int countHousePlacements(int n) {
        long MOD = 1_000_000_007L;
        long a = 1, b = 2;
        for (int i = 0; i < n; i++) {
            long nextB = (a + b) % MOD;
            a = b;
            b = nextB;
        }
        return (int) ((a * a) % MOD);
    }
}

var countHousePlacements = function(n) {
    const MOD = 1000000007n;
    let a = 1n, b = 2n;
    for (let i = 0; i < n; i++) {
